{
  "business_goal": "첫 구매 고객 중 재구매 가능성이 낮은 고객에게 쿠폰을 보내 재구매를 유도해 쿠폰 발송 비용을 줄이고 재구매율을 높인다",
  "prediction_target": "첫 구매 고객",
  "analysis_unit": "고객",
  "prediction_time": "첫 구매 직후",
  "target_definition": "첫 구매 후 재구매 여부",
  "success_metric": null,
  "constraints": [],
  "requirement_items": [
    {"id": "R1", "text": "첫 구매 고객 대상", "kind": "population"},
    {"id": "R2", "text": "첫 구매 직후 쿠폰 발송", "kind": "constraint"},
    {"id": "R3", "text": "첫 주문 금액, 결제 수단, 할부 여부, 구매 카테고리, 고객 지역 정보 활용", "kind": "feature"},
    {"id": "R4", "text": "쿠폰 대상은 신규 고객의 상위 20% 수준", "kind": "constraint"}
  ],
  "open_questions": [
    {"id": "Q1", "question": "성공 지표를 어떤 지표로 판단할까요?", "target_field": "success_metric", "options": ["재구매율", "쿠폰 발송 비용 대비 재구매 증가율"], "default_option": "재구매율", "reason": "성공 지표가 명시되지 않았으므로 재구매율을 기본으로 제안"},
    {"id": "Q2", "question": "재구매 가능성이 낮은 고객을 정의하는 기준은 무엇인가요?", "target_field": "target_definition", "options": ["첫 구매 후 일정 기간 내 재구매 여부", "첫 구매 금액 기준"], "default_option": "첫 구매 후 일정 기간 내 재구매 여부", "reason": "재구매 가능성이 낮은 고객을 정의하는 기준이 명시되지 않았으므로 첫 구매 후 일정 기간 내 재구매 여부를 기본으로 제안"}
  ],
  "rationale": "필수 항목이 모두 명시되었으나 성공 지표와 재구매 가능성이 낮은 고객을 정의하는 기준이 빠져 질문으로 남겼다."
}

